import 'package:flutter/material.dart';

class BrandMark extends StatelessWidget { const BrandMark({super.key, this.large = false}); final bool large; @override Widget build(BuildContext context) => Row(mainAxisSize: MainAxisSize.min, children: [Container(width: large ? 42 : 32, height: large ? 42 : 32, decoration: BoxDecoration(color: Theme.of(context).colorScheme.primary, borderRadius: BorderRadius.circular(10)), child: Icon(Icons.grid_view_rounded, color: Colors.white, size: large ? 25 : 19)), const SizedBox(width: 10), Text('vertal', style: TextStyle(fontSize: large ? 30 : 20, fontWeight: FontWeight.w800, letterSpacing: -0.5))]); }
class SectionTitle extends StatelessWidget { const SectionTitle(this.title, {super.key, this.action}); final String title; final VoidCallback? action; @override Widget build(BuildContext context) => Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Text(title, style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.w800)), if (action != null) IconButton(onPressed: action, icon: const Icon(Icons.add_circle_outline))]); }
class StatusPill extends StatelessWidget { const StatusPill(this.label, {super.key, this.color = const Color(0xFF0E7490)}); final String label; final Color color; @override Widget build(BuildContext context) => Container(padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 5), decoration: BoxDecoration(color: color.withValues(alpha: .12), borderRadius: BorderRadius.circular(20)), child: Text(label, style: TextStyle(color: color, fontWeight: FontWeight.w700, fontSize: 11))); }
class EmptyState extends StatelessWidget { const EmptyState({super.key, required this.icon, required this.title, required this.message}); final IconData icon; final String title; final String message; @override Widget build(BuildContext context) => Center(child: Padding(padding: const EdgeInsets.all(32), child: Column(mainAxisSize: MainAxisSize.min, children: [Icon(icon, size: 42, color: Colors.blueGrey.shade300), const SizedBox(height: 14), Text(title, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w800)), const SizedBox(height: 6), Text(message, textAlign: TextAlign.center, style: TextStyle(color: Colors.blueGrey.shade600))]))); }
void showMessage(BuildContext context, String message) => ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message), behavior: SnackBarBehavior.floating));